from solution import No_of_Triangle


def test_issue_example_4_2():
    """Example requires No_of_Triangle(4,2) == 7."""
    assert No_of_Triangle(4, 2) == 7  # (3*4)//2=6 upright + (1*2)//2=1 inverted = 7


def test_issue_smallest_grid_1_1():
    """Count the maximum number for smallest triangle N=1,K=1 is 1."""
    assert No_of_Triangle(1, 1) == 1  # (1*2)//2=1 upright + 0 inverted = 1


def test_issue_k_equals_n_3_3():
    """Count when small side equals big side N=K is 1."""
    assert No_of_Triangle(3, 3) == 1  # (1*2)//2=1 upright + 0 inverted (3<6) = 1


def test_issue_k_greater_than_n_2_5():
    """Count when K exceeds N must be 0 triangles."""
    assert No_of_Triangle(2, 5) == 0  # no side-5 fit in side-2, so 0


def test_issue_unit_triangles_5_1():
    """Count of unit triangles in side N equals N squared."""
    assert No_of_Triangle(5, 1) == 25  # (5*6)//2=15 upright + (4*5)//2=10 inverted = 25


def test_issue_unit_grid_2_1():
    """Count the maximum number for N=2,K=1 is 4."""
    assert No_of_Triangle(2, 1) == 4  # (2*3)//2=3 upright + (1*2)//2=1 inverted = 4


def test_issue_below_inverted_threshold_3_2():
    """Count with N just below 2*K has no inverted triangles."""
    assert No_of_Triangle(3, 2) == 3  # (2*3)//2=3 upright + 0 inverted (3<4) = 3


def test_issue_at_inverted_threshold_6_3():
    """Count with N equal to 2*K adds exactly one inverted triangle."""
    assert No_of_Triangle(6, 3) == 11  # (4*5)//2=10 upright + (1*2)//2=1 inverted = 11


def test_issue_above_inverted_threshold_5_2():
    """Count with N just above 2*K includes inverted triangles."""
    assert No_of_Triangle(5, 2) == 13  # (4*5)//2=10 upright + (2*3)//2=3 inverted = 13


def test_issue_larger_mixed_6_2():
    """Count the maximum number for N=6,K=2 is 21."""
    assert No_of_Triangle(6, 2) == 21  # (5*6)//2=15 upright + (3*4)//2=6 inverted = 21


def test_contract_deterministic():
    """Repeated counting with same N,K must give same maximum number."""
    assert No_of_Triangle(5, 2) == No_of_Triangle(5, 2)  # both calls equal 13


def test_contract_nonnegative_count():
    """Count the maximum number of triangles must never be negative."""
    assert No_of_Triangle(3, 2) >= 0  # expected 3, hence >= 0
